```cpp
#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

// 快速幂：计算 a^e mod MOD
long long modpow(long long a, long long e) {
	long long r = 1 % MOD;
	a %= MOD;
	while (e > 0) {
		if (e & 1) r = (r * a) % MOD;
		a = (a * a) % MOD;
		e >>= 1;
	}
	return r;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int T;
	if (!(cin >> T)) return 0;
	while (T--) {
		int n;
		long long r;
		cin >> n >> r;
		long long L = r - 1; // 允许的最大连续1长度
		if (L >= n) {
			// 限制无效，答案为 2^n
			cout << modpow(2, n) << "\n";
			continue;
		}
		// 需要按递推计算
		vector<long long> f(n + 1, 0);
		f[0] = 1; // 空串
		// 预处理 0..L 上的 2^i
		long long pw = 1;
		for (int i = 1; i <= (int)L; ++i) {
			pw = (pw * 2) % MOD;
			f[i] = pw; // f[i] = 2^i
		}
		// 注意 f[0] 需要是 2^0=1，已设
		// 计算初始窗口 W = sum_{k=0..r-1} f[k]，其中 r = L+1
		int R = (int)r; // 窗口宽度
		long long W = 0;
		for (int k = 0; k <= (int)L; ++k) {
			long long val = (k == 0 ? f[0] : f[k]);
			// f[0] 已是 1，f[1..L] 已是 2^i
			if (k == 0 && f[0] == 0) val = 1; // 保护（理论不会触发）
			W += (k == 0 ? f[0] : f[k]);
			if (W >= MOD) W -= MOD;
		}
		// 递推 i = r..n
		for (int i = R; i <= n; ++i) {
			f[i] = W;
			W += f[i];
			if (W >= MOD) W -= MOD;
			W -= f[i - R];
			if (W < 0) W += MOD;
		}
		cout << f[n] % MOD << "\n";
	}
	return 0;
}
