```python
import sys

MOD = 10**9 + 7

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out = []
    for _ in range(T):
        n = int(next(it))
        k = int(next(it))
        # 若 k-1 >= n，即最大允许的连续1长度大于等于n，任何序列都合法
        if k - 1 >= n:
            out.append(str(pow(2, n, MOD)))
            continue
        L = k - 1  # 允许的最大连续1长度
        dp = [0] * (n + 1)
        dp[0] = 1
        # 初始化 1..L
        pw = 1
        for i in range(1, L + 1):
            pw = (pw * 2) % MOD
            dp[i] = pw
        # 窗口大小 = k，即 dp[0..L] 共 k 个元素
        W = sum(dp[:k]) % MOD  # 取前k项
        for i in range(k, n + 1):
            dp[i] = W
            # 更新滑动窗口
            W = (W + dp[i] - dp[i - k]) % MOD
        out.append(str(dp[n] % MOD))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
```

